package com.nexushr.controller; import com.nexushr.service.DashboardService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController @RequestMapping("/dashboard") public class DashboardController {final DashboardService s;public DashboardController(DashboardService s){this.s=s;} @GetMapping @PreAuthorize("hasAnyRole('ADMIN','HR')") public Map<String,Object> dashboard(){return s.dashboard();} @GetMapping("/ai-insights") @PreAuthorize("hasAnyRole('ADMIN','HR')") public Map<String,Object> insights(){return s.insights();}}
